"use client";

import React from "react";
import { updateOrder } from "@/app/BookAPI";
import Link from "next/link";
import { useState } from "react";

const Page = ({ params }: { params: { id: string } }) => {
 const { id } = params;

 const [customerName, setCustomerName] = useState("");
 const [orderStatus, setOrderStatus] = useState(null);

 const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const orderStatusResult = await updateOrder(id, customerName);
    setOrderStatus(orderStatusResult);
  };

  return (
    <div>
      <div>
        <h1>Update Order</h1>
      </div>
      <div>
        <form onSubmit={handleSubmit}>
          <div>
            Customer Name
            <input
              type="text"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
            />
          </div>
          <div>
            <button type="submit">Update Order</button>
          </div>
        </form>
        {orderStatus && <div>Order Status: {orderStatus}</div>}
      </div>
    </div>
  );
};

export default Page;
```

In this updated code, I've added a new state variable `orderStatus` to store the result of the `updateOrder` function call. The `handleSubmit` function now updates the `orderStatus` state after the promise resolves. The JSX part checks if `orderStatus` is not null and renders the order status message accordingly.
