// Define the interface for the user data
interface User {
  birthDate: string;
  location: {
    continent: string;
    country: string;
    city: string;
  };
  gender: string;
  name: {
    first: string;
    last: string;
  };
  phone: string;
  registered: string;
  email: string;
}

// Fetch data from the endpoint
async function fetchData() {
  const response = await fetch('https://randomuser.me/api/?results=20');
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const data = await response.json();

  // Process the data
  processData(data.results as User[]);
}

// Process the data and display the first name, last name, and email of each user
function processData(users: User[]) {
  users.forEach((user) => {
    console.log(`Name: ${user.name.first} ${user.name.last}, Email: ${user.email}`);
  });
}

// Call the fetchData function
fetchData();
